    @Test void ordinaryDisjointCallsKeepTheirExistingOwnershipAndDoNotTakeHeavyRerouteQuota()throws Exception {
        try(var f=new Fixture()) {
            var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var first=f.source.target.ranges().getFirst();
            try(var data=new RatisRoutedClient(f.source.target,new RatisRoutedClient.Transport(){
                public byte[] read(RangeDescriptor route,UUID column,byte[] key){throw new AssertionError();}
                public CommandResult command(RangeDescriptor route,DistributedCommand command)throws IOException {if(route.groupId().equals(first.groupId())){entered.countDown();try{if(!release.await(5,TimeUnit.SECONDS))throw new IOException("Ordinary fixture timed out");}catch(InterruptedException interrupted){Thread.currentThread().interrupt();throw new IOException(interrupted);}}return new CommandResult(CommandResult.Status.SUCCESS,List.of());}
            });var coordinator=new RatisOperationRerouteCoordinator(root.resolve("ordinary-reroutes"),f.source.schema,f.catalogue.epochs,data,f.homes,f.scheduler,f.window.grant(),f.window.limits(),f.catalogue.epochs.catalogue(f.outer.directoryColumn),header->f.source.directory);var callers=Executors.newVirtualThreadPerTaskExecutor()) {
                var one=data.prepare(new OperationId(f.window.grant().sessionId(),f.window.grant().epoch(),0),List.of(new Mutation(Mutation.Kind.PUT,f.source.column,new byte[]{10},new byte[]{1})));var two=data.prepare(new OperationId(f.window.grant().sessionId(),f.window.grant().epoch(),1),List.of(new Mutation(Mutation.Kind.PUT,f.source.column,new byte[]{(byte)200},new byte[]{2})));
                var blocked=callers.submit(()->coordinator.execute(one,RequestContext.batch(),()->{}));
                try{assertTrue(entered.await(5,TimeUnit.SECONDS));assertThrows(IOException.class,coordinator::close);assertEquals(CommandResult.Status.SUCCESS,coordinator.execute(two,RequestContext.batch(),()->{}).status());}finally{release.countDown();}
                assertEquals(CommandResult.Status.SUCCESS,blocked.get(5,TimeUnit.SECONDS).status());
            }
        }
    }
